import { useMemo, useState } from 'react'
import { AlertTriangle, CircleDot, FileSearch, GitBranch, Link2, ShieldAlert, ShieldCheck, Target } from 'lucide-react'
import { neighbors, type AssuranceGraph, type AssuranceNode } from './AssuranceGraph'

const iconFor: Record<AssuranceNode['type'], typeof Target> = {
  finding: ShieldAlert, asset: ShieldCheck, service: GitBranch, endpoint: CircleDot, evidence: FileSearch,
  validation: Target, control: ShieldCheck, threat: AlertTriangle, data: CircleDot, remediation: Target,
}

export function AssuranceGraphView({ graph, onInvestigate }: { graph: AssuranceGraph; onInvestigate?: (node: AssuranceNode) => void }) {
  const [selectedId, setSelectedId] = useState(graph.nodes[0]?.id ?? null)
  const selected = graph.nodes.find((node) => node.id === selectedId)
  const connected = useMemo(() => new Set([selectedId, ...(selectedId ? neighbors(graph, selectedId).map((n) => n.id) : [])]), [graph, selectedId])
  const select = (node: AssuranceNode) => { setSelectedId(node.id); onInvestigate?.(node) }
  if (!graph.nodes.length) return <section className="rounded-2xl border bg-card p-8 text-center text-sm text-muted-foreground">No assurance graph data available.</section>
  const columns: AssuranceNode['type'][] = ['finding', 'threat', 'asset', 'service', 'endpoint', 'control', 'evidence', 'validation', 'remediation', 'data']
  const groups = columns.map((type) => graph.nodes.filter((node) => node.type === type)).filter((group) => group.length)
  const positions = new Map<string, { x: number; y: number }>()
  groups.forEach((group, gi) => group.forEach((node, ni) => positions.set(node.id, { x: 75 + gi * 170, y: 55 + ni * 85 })))
  const width = Math.max(1100, groups.length * 170 + 80)
  return <section className="overflow-hidden rounded-2xl border bg-card"><header className="flex flex-wrap items-center justify-between gap-3 border-b px-5 py-4"><div><div className="flex items-center gap-2 font-semibold"><Link2 className="h-4 w-4 text-primary" /> Unified Assurance Graph</div><p className="mt-1 text-xs text-muted-foreground">One graph for findings, assets, controls, evidence, validations, threats, and remediation.</p></div><div className="text-[10px] text-muted-foreground">{graph.nodes.length} nodes · {graph.edges.length} relations</div></header><div className="overflow-auto p-4"><div className="relative min-h-[430px]" style={{ width }}><svg className="pointer-events-none absolute inset-0 h-full w-full" viewBox={`0 0 ${width} 430`} preserveAspectRatio="none"><defs><marker id="assurance-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="currentColor" /></marker></defs>{graph.edges.map((edge) => { const a = positions.get(edge.from), b = positions.get(edge.to); if (!a || !b) return null; const active = connected.has(edge.from) && connected.has(edge.to); return <path key={edge.id} d={`M ${a.x + 60} ${a.y + 20} C ${(a.x + b.x) / 2} ${a.y + 20}, ${(a.x + b.x) / 2} ${b.y + 20}, ${b.x - 60} ${b.y + 20}`} fill="none" stroke="currentColor" markerEnd="url(#assurance-arrow)" strokeWidth={active ? 2.5 : 1} strokeDasharray={active ? '7 5' : undefined} className={active ? 'text-primary' : 'text-muted-foreground/20'} />})}</svg>{graph.nodes.map((node) => { const p = positions.get(node.id)!; const Icon = iconFor[node.type]; const active = node.id === selectedId; const related = connected.has(node.id); return <button key={node.id} type="button" onClick={() => select(node)} style={{ left: p.x - 60, top: p.y }} aria-pressed={active} className={`absolute z-10 w-[120px] rounded-xl border bg-card p-2.5 text-left shadow-sm transition ${active ? 'ring-2 ring-primary/60' : ''} ${selectedId && !related ? 'opacity-20 saturate-0' : 'opacity-100'}`}><div className="flex items-center gap-2"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-lg border"><Icon className="h-3.5 w-3.5" /></span><span className="min-w-0 truncate text-[10px] font-semibold">{node.label}</span></div><div className="mt-2 flex flex-wrap gap-1">{node.severity && <span className="rounded-full border px-1.5 py-0.5 text-[8px]">{node.severity}</span>}{node.confidence !== undefined && <span className="rounded-full border px-1.5 py-0.5 text-[8px]">{Math.round(node.confidence)}%</span>}{node.conflictCount ? <span className="rounded-full border border-amber-500/30 px-1.5 py-0.5 text-[8px] text-amber-600">{node.conflictCount} conflict</span> : null}</div></button> })}</div></div>{selected && <footer className="flex flex-wrap items-center justify-between gap-3 border-t bg-muted/20 px-5 py-4"><div><div className="text-[10px] uppercase tracking-wider text-muted-foreground">Selected entity</div><div className="mt-1 text-sm font-semibold">{selected.label}</div></div><button type="button" onClick={() => onInvestigate?.(selected)} className="inline-flex items-center gap-2 rounded-lg bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground"><Target className="h-3.5 w-3.5" /> Open investigation</button></footer>}</section>
}
